+import express from "express";
+import multer from "multer";
+
+export const avatars = express.Router();
+const upload = multer({ storage: multer.memoryStorage() });
+const files = new Map<string, { body: Buffer; type: string }>();
+const png = (b: Buffer) => b.subarray(0, 8).equals(Buffer.from("89504e470d0a1a0a", "hex"));
+const jpeg = (b: Buffer) => b.subarray(0, 3).equals(Buffer.from("ffd8ff", "hex"));
+
+avatars.post("/avatars", upload.single("image"), (req, res) => {
+  if (!req.file || (!png(req.file.buffer) && !jpeg(req.file.buffer))) return res.sendStatus(400);
+  const id = crypto.randomUUID();
+  files.set(id, { body: req.file.buffer, type: png(req.file.buffer) ? "image/png" : "image/jpeg" });
+  res.status(201).json({ id });
+});
+
+avatars.get("/avatars/:id", (req, res) => {
+  const file = files.get(req.params.id);
+  if (!file) return res.sendStatus(404);
+  res.set({ "Content-Type": file.type, "X-Content-Type-Options": "nosniff", "Content-Disposition": "attachment" }).send(file.body);
+});

